record.field:
hoy = date.today()
desde_mes = int(self.env['hr.rule.parameter']._get_parameter_from_code('l10n_co_aviso_anio_siguiente_desde_mes'))
anios = [hoy.year] + ([hoy.year + 1] if hoy.month >= desde_mes else [])
Config = self.env['l10n.co.retefuente.uvt']
faltan = []
for compania in self.env.companies.filtered(lambda c: c.partner_id.country_id.code == 'CO'):
    for anio in anios:
        if not Config._ne_config_del_anio(anio, compania):
            faltan.append((compania, anio))
if faltan:
    warning_count = len(faltan)
    detalle = ', '.join('%s (%s)' % (c.name, a) for c, a in faltan)
    primera_compania, primer_anio = faltan[0]
    warning_action = {
        'type': 'ir.actions.act_window',
        'name': 'Colombia: configuración de retención sin cargar: ' + detalle,
        'res_model': 'l10n.co.retefuente.uvt',
        # Un solo faltante: abre el formulario de creación con el año y la compañía precargados;
        # varios: la lista (el botón Nuevo precarga el primero).
        'views': [[False, 'form']] if len(faltan) == 1 else [[False, 'list'], [False, 'form']],
        'view_mode': 'form' if len(faltan) == 1 else 'list,form',
        'context': {'default_year': str(primer_anio), 'default_company_id': primera_compania.id},
    }
